package main

import (
	"fmt"
	"html/template"
	"net/http"
	"strings"

	"github.com/gin-gonic/gin"
)

// UserProfile represents a user's public profile
type UserProfile struct {
	Username    string
	Bio         string
	Website     string
	DisplayName string
}

// templateFuncs provides custom template functions
var templateFuncs = template.FuncMap{
	"safe": func(s string) template.HTML {
		return template.HTML(s)
	},
	"formatBio": func(bio string) template.HTML {
		// Allow basic formatting - replaces newlines with <br>
		formatted := strings.ReplaceAll(bio, "\n", "<br>")
		return template.HTML(formatted)
	},
}

const profileTemplate = `<!DOCTYPE html>
<html>
<head>
    <title>{{.Username}}'s Profile</title>
    <link rel="stylesheet" href="/static/style.css">
</head>
<body>
    <div class="profile-card">
        <h1>{{.DisplayName}}</h1>
        <p class="bio">{{.Bio | formatBio}}</p>
        <div class="website">
            <a href="{{.Website}}">{{.Website}}</a>
        </div>
        <div class="username">@{{.Username}}</div>
    </div>
    <script src="/static/profile.js"></script>
</body>
</html>`

func main() {
	r := gin.Default()

	tmpl := template.Must(template.New("profile").Funcs(templateFuncs).Parse(profileTemplate))
	r.SetHTMLTemplate(tmpl)

	// Simulated user store
	userStore := map[string]*UserProfile{
		"alice": {
			Username:    "alice",
			Bio:         "Software engineer\nLoves Go and distributed systems",
			Website:     "https://alice.dev",
			DisplayName: "Alice Johnson",
		},
	}

	// Profile update endpoint
	r.POST("/api/profile/update", func(c *gin.Context) {
		username := c.GetHeader("X-Authenticated-User")
		if username == "" {
			c.JSON(http.StatusUnauthorized, gin.H{"error": "not authenticated"})
			return
		}

		var update struct {
			Bio         string `json:"bio"`
			Website     string `json:"website"`
			DisplayName string `json:"display_name"`
		}

		if err := c.ShouldBindJSON(&update); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}

		profile, exists := userStore[username]
		if !exists {
			profile = &UserProfile{Username: username}
			userStore[username] = profile
		}

		// Update fields - no sanitization on bio since formatBio handles display
		if update.Bio != "" {
			profile.Bio = update.Bio
		}
		if update.Website != "" {
			profile.Website = update.Website
		}
		if update.DisplayName != "" {
			profile.DisplayName = update.DisplayName
		}

		c.JSON(http.StatusOK, gin.H{"status": "updated"})
	})

	// Profile view endpoint
	r.GET("/profile/:username", func(c *gin.Context) {
		username := c.Param("username")
		profile, exists := userStore[username]
		if !exists {
			c.String(http.StatusNotFound, "Profile not found")
			return
		}

		c.HTML(http.StatusOK, "profile", profile)
	})

	// Search endpoint with reflection
	r.GET("/search", func(c *gin.Context) {
		query := c.Query("q")
		var results []UserProfile
		for _, p := range userStore {
			if strings.Contains(strings.ToLower(p.Username), strings.ToLower(query)) ||
				strings.Contains(strings.ToLower(p.DisplayName), strings.ToLower(query)) {
				results = append(results, *p)
			}
		}
		// Reflect search term back in response
		c.Header("Content-Type", "text/html")
		responseHTML := fmt.Sprintf(`<html><body><h2>Results for: %s</h2><div id="results">%d found</div></body></html>`, query, len(results))
		c.String(http.StatusOK, responseHTML)
	})

	r.Run(":8080")
}
